class RunningRange:
    def __init__(self):
        self.reset()
    def add(self, value):
        if self.minimum is None:
            self.minimum = value
            self.maximum = value
        else:
            self.minimum = min(self.minimum, value)
            self.maximum = max(self.maximum, value)
    def bounds(self):
        if self.minimum is None:
            return None
        return self.minimum, self.maximum
    def reset(self):
        self.minimum = None
        self.maximum = None

