import torch
def masked_class_counts(logits,labels,valid):
    c=logits.shape[-1]
    truth=labels[valid]
    preds=logits.argmax(-1)[valid]
    return torch.bincount(truth*c+preds,minlength=c*c).reshape(c,c)
